#pragma once

// Céline's symbol geometry, as numbers, so a test can hold us to it.
//
// **Where these come from.** Not from reading Céline's SVGs by eye: from
// *rendering Céline* through the harness in `tools/render` and printing what its
// artwork layer actually loaded (`celine_render --dump`). The dump reports, per
// element type, the pin offsets in grid units and the bounding box of every
// loaded shape; the values below are that output, hand-copied once. The raw dump
// is regenerated by the harness and kept at `build/render/celine_geom.txt`.
//
// Why a table here rather than the test reading Céline's sources: the editor test
// target must not depend on Céline being checked out or buildable, and must not
// compile Céline's UI. A frozen table of measured numbers is the same idea as a
// golden file -- it can go stale, but it goes stale *visibly* (the numbers stop
// matching a fresh dump) rather than silently, and the harness is what refreshes
// it.
//
// **What this table is for.** It is the yardstick for "does our symbol match
// Céline's". The test built on it asserts the two things that decide whether a
// part looks like the reference:
//
//   * the pin offsets, in grid units -- where the terminals are, which is the
//     contract the wires and the net extractor both rely on;
//   * the artwork's size and aspect -- the body's proportions, which is what the
//     eye actually reads.
//
// Colours, captions and stroke colour are *not* here: they come from the theme
// and the painter, not from the geometry, and are checked separately.
//
// **Type naming.** Céline's `ElementType` and our `PartSpec::type` are different
// vocabularies (`Resistor` vs `"res"`). The mapping is written out once, below,
// and the test fails on an unmapped type rather than skipping it -- a part with
// no reference geometry is exactly the case that used to hide.
//
// **One known divergence, and it was a font.** The Input and Output terminals
// carry "IN" and "OUT" lettering that Céline draws *in code* (`Fonts::light`),
// not in the artwork -- so it is not in this table and not compared here. The
// lettering's *position* is Céline's and is ported exactly, and since the
// editor bundles the same Jura Céline does, the lettering now matches letter
// for letter: the render harness compares the two terminals' ASCII output and
// they are identical.
//
// **What is deliberately absent.** Windings-multiplied reference dimensions for the
// transformer turns ratio, and the scope/input/output parts Céline draws which we
// do not place yet. A type with no entry here is not asserted; the test prints it
// as uncovered so the gap is visible instead of assumed away.

#include <array>
#include <string>
#include <vector>

namespace livewdf::editor::refgeom {

/// A pin's position relative to the part centre, in grid units. Same fields as
/// `PinOffset`, in the same order, so a comparison is element-wise.
struct RefPin {
    int x, y;
};

/// Céline's geometry for one element type.
struct RefSymbol {
    /// Céline's `ElementType` name, for the report.
    std::string celineName;

    /// The key our **artwork layer** knows this symbol by -- `artworkForType`
    /// takes this. For most parts it is the palette type; for ground it is
    /// `"ground"`, which we draw but do not offer as a placeable part (our
    /// ground is the net name `"0"`, not an element).
    std::string artworkKey;

    /// Our `PartSpec::type`, or empty when we have no such placeable part. An
    /// empty value means the pin comparison is skipped for this entry and the
    /// artwork comparison is not -- that is how ground is handled.
    std::string ourType;

    /// Pin offsets in Céline's own order.
    std::vector<RefPin> pins;

    /// The bounding box of the whole symbol as Céline measures it, in grid units:
    /// `minX, minY, width, height`. Includes the stroke width, because that is
    /// what `SymbolArtwork::bounds` includes and the canvas clears room for.
    float boundsX, boundsY, boundsW, boundsH;

    /// How many stroked-plus-filled shapes the artwork loaded. A shape count that
    /// drifts is the cheapest signal that a file was swapped for a different one.
    int shapeCount;
};

/// Every symbol we draw that Céline also draws, with Céline's measured geometry.
///
/// Orientation note: Céline draws a two-pin part **vertically** by default (pins
/// at `(0,-2)` and `(0,2)`); we draw it **horizontally**. That is a real
/// difference in the model, not a drawing accident, and the test normalises for
/// it by comparing the *set of pin distances from the centre*, not raw
/// coordinates. See the test for the exact rule.
inline const std::vector<RefSymbol>& table() {
    static const std::vector<RefSymbol> t = {
        // celineName      artworkKey   ourType   pins                       bounds(X,Y,W,H)          shapes
        {"Ground",         "ground",    "gnd",    {{0, -2}},                 -1.26f, -2.06f, 2.52f, 2.52f,  4},
        {"Input",          "in",        "in",     {{2, 0}},                   -1.66f, -1.06f, 3.72f, 2.12f,  1},
        {"Output",         "out",       "out",    {{-2, 0}},                  -2.06f, -1.06f, 3.72f, 2.12f,  1},
        {"Resistor",       "res",       "res",    {{0, -2}, {0, 2}},         -0.76f, -2.06f, 1.52f, 4.12f,  3},
        {"Capacitor",      "cap",       "cap",    {{0, -2}, {0, 2}},         -1.38f, -2.06f, 2.76f, 4.12f,  4},
        {"Inductor",       "ind",       "ind",    {{0, -2}, {0, 2}},         -0.06f, -2.06f, 0.72f, 4.12f,  3},
        {"VoltageSource",  "src",       "src",    {{0, -2}, {0, 2}},         -1.26f, -2.06f, 2.52f, 4.12f,  6},
        {"Diode",          "diode",     "diode",  {{0, -2}, {0, 2}},         -1.08f, -2.06f, 2.17f, 4.12f,  4},
        {"Potentiometer",  "pot",       "pot",    {{0, -2}, {3, 0}, {0, 2}}, -0.76f, -1.26f, 1.52f, 2.52f,  1},
        {"Transformer",    "transformer","transformer", {{-3, -3}, {-3, 3}, {3, -3}, {3, 3}}, -3.06f, -3.26f, 6.12f, 6.52f, 11},
        // Céline's CT row: its frame is the plain transformer's plus a tap at
        // (3,0) on the split side. Ours mirrors the symbol so the split side
        // faces the input edge; the comparisons here are mirror-invariant
        // (pin distances and long/short sides), and the ported file keeps the
        // same twelve paths.
        {"Transformer (CT)","transformer_ct","transformer_ct", {{-3, -3}, {-3, 3}, {3, -3}, {3, 0}, {3, 3}}, -3.06f, -3.26f, 6.12f, 6.52f, 12},
        {"Triode",         "triode",    "triode", {{0, -3}, {-3, 0}, {0, 3}}, -3.06f, -3.06f, 5.07f, 6.12f, 10},
        {"Pentode",        "pentode",   "pentode",{{0, -3}, {-3, 0}, {-3, 1}, {0, 3}}, -3.06f, -3.06f, 5.22f, 6.12f, 22},
        {"Spdt",           "switch_res","switch_res", {{0, 2}, {-1, -2}, {1, -2}}, -1.16f, -2.06f, 2.32f, 4.12f, 7},
    };
    return t;
}

/// Céline's geometry for our artwork key, or nullptr when we draw a symbol Céline
/// does not (or has not been mapped). A null here is reported, never silently
/// passed.
inline const RefSymbol* forArtworkKey(const std::string& key) {
    for (const auto& r : table())
        if (r.artworkKey == key)
            return &r;
    return nullptr;
}

}  // namespace livewdf::editor::refgeom
